/* penny.js - photorealistic US one-cent coin (Lincoln cent, union-shield reverse) for the Drone renders, true to scale.
 * designer 2026-11-09: a US penny lies flat on the grid, obverse up, in every render, as a size reference.
 * Spec (US Mint): 19.05 mm diameter, 1.52 mm thick, copper-plated zinc, plain (unreeded) edge.
 * Usage (global THREE, works from file://, no fetch): var p = PennyModel.make(); p.position.set(x, groundY, z); scene.add(p);
 *   the group's origin is the centre of the coin's bottom face. PennyModel.D / PennyModel.T give the size in mm.
 * Textures (embedded below as JPEG data URIs, 384 px; full-size circular PNGs beside this file):
 *   obverse: lib/penny_obverse.png from Wikimedia Commons "File:2010 cent obverse.png" (United States Mint image; designer
 *     Victor David Brenner; public domain, US government work).
 *   reverse: lib/penny_reverse.png from Wikimedia Commons "File:Union Shield Cent.jpg" (photo by Leopard2A7m, CC BY-SA 4.0;
 *     no public-domain US Mint image of the 2010+ union-shield reverse could be fetched on 2026-11-09: usmint.gov returns 403).
 *     It faces the grid in every render. Attribution kept here and in lib/README_penny.md.
 * Materials: copper MeshStandardMaterial, metalness 0.9, roughness 0.35, with a small built-in gradient environment map so
 * the metal reads as copper instead of black in scenes that have no environment. Opaque.
 */
(function (global) {
  'use strict';
  var OBV = 'data:image/jpeg;base64,';
  var REV = 'data:image/jpeg;base64,';
  var D = 19.05, T = 1.52;
  var env = null;
  function envMap(THREE) {            // soft studio gradient (light above, warm grey below) as an equirect env map
    if (env) return env;
    var c = document.createElement('canvas'); c.width = 256; c.height = 128;
    var x = c.getContext('2d'), g = x.createLinearGradient(0, 0, 0, 128);
    g.addColorStop(0, '#ffffff'); g.addColorStop(0.35, '#d9dcdf'); g.addColorStop(0.5, '#9a9ea3'); g.addColorStop(1, '#4a4d52');
    x.fillStyle = g; x.fillRect(0, 0, 256, 128);
    x.fillStyle = 'rgba(255,255,255,0.9)'; x.fillRect(40, 10, 60, 18); x.fillRect(150, 14, 50, 14);   // two softboxes
    env = new THREE.CanvasTexture(c); env.mapping = THREE.EquirectangularReflectionMapping; env.colorSpace = THREE.SRGBColorSpace;
    return env;
  }
  function tex(THREE, uri, rot) {
    var img = new Image(), t = new THREE.Texture(img);
    img.onload = function () { t.needsUpdate = true; };
    img.src = uri;
    t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 8; t.center.set(0.5, 0.5); t.rotation = rot || 0;
    if (img.complete) t.needsUpdate = true;
    return t;
  }
  function make(opts) {
    var THREE = global.THREE; opts = opts || {};
    var e = envMap(THREE);
    var copper = { metalness: 0.9, roughness: 0.35, envMap: e, envMapIntensity: 1.0 };
    var edge = new THREE.MeshStandardMaterial(Object.assign({ color: 0xc27a52 }, copper));
    var top = new THREE.MeshStandardMaterial(Object.assign({ color: 0xffffff, map: tex(THREE, OBV, opts.obvRot !== undefined ? opts.obvRot : Math.PI / 2) }, copper));
    var bot = new THREE.MeshStandardMaterial(Object.assign({ color: 0xffffff, map: tex(THREE, REV, opts.revRot !== undefined ? opts.revRot : -Math.PI / 2) }, copper));
    var geo = new THREE.CylinderGeometry(D / 2, D / 2, T, 96, 1, false);   // groups: 0 edge, 1 top cap, 2 bottom cap
    var m = new THREE.Mesh(geo, [edge, top, bot]);
    m.position.y = T / 2; m.castShadow = true; m.receiveShadow = true;
    var g = new THREE.Group(); g.add(m); g.name = 'US penny';
    if (opts.yaw) g.rotation.y = opts.yaw;
    return g;
  }
  global.PennyModel = { make: make, D: D, T: T };
})(window);
